#include <iostream>
#include <vector>
#include <string>

using namespace std;

/**
 * Problem: 22821 - Oil Deposits
 * 
 * 解題思路：
 * 1. 給定一個網格，包含 '*'（無油）和 '@'（油坑）。
 * 2. 如果兩個油坑相鄰（包括水平、垂直、對角線共 8 個方向），則它們屬於同一個油田。
 * 3. 目標是計算網格中有多少個獨立的油田。
 * 4. 這是典型的連通分量 (Connected Components) 問題。
 * 5. 使用深度優先搜尋 (DFS) 或廣度優先搜尋 (BFS) 遍歷網格：
 *    - 遍歷每個格子，如果遇到未訪問過的 '@'，則代表發現一個新油田。
 *    - 從該點開始 DFS，將所有連通的 '@' 標記為已訪問。
 *    - 累計發現的次數即為答案。
 */

int m_rows, n_cols;
vector<string> grid;
vector<vector<bool>> visited;

void dfs(int r, int c) {
    if (r < 0 || r >= m_rows || c < 0 || c >= n_cols || visited[r][c] || grid[r][c] != '@')
        return;

    visited[r][c] = true;

    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr != 0 || dc != 0) {
                dfs(r + dr, c + dc);
            }
        }
    }
}

int main() {
    while (cin >> m_rows >> n_cols && m_rows != 0) {
        grid.resize(m_rows);
        visited.assign(m_rows, vector<bool>(n_cols, false));
        for (int i = 0; i < m_rows; i++) cin >> grid[i];

        int count = 0;
        for (int i = 0; i < m_rows; i++) {
            for (int j = 0; j < n_cols; j++) {
                if (grid[i][j] == '@' && !visited[i][j]) {
                    count++;
                    dfs(i, j);
                }
            }
        }
        cout << count << endl;
    }
    return 0;
}
